package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.config.OutboxProperties;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import com.sun.net.httpserver.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-outbox-dispatch：只连接隔离数据库和本机HTTP模拟端。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.outbox-dispatch.real",matches="true") @EnabledIfSystemProperty(named="ar.outbox-dispatch.real.commit",matches="true")
class OutboxDispatchRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired JdbcTemplate jdbc;@Autowired OutboxProperties config;@Autowired OutboxDispatchService service;@Autowired org.springframework.transaction.PlatformTransactionManager transactions;
 HttpServer server;ExecutorService executor;long scope;AtomicInteger calls=new AtomicInteger();AtomicReference<String> body=new AtomicReference<>(),authorization=new AtomicReference<>(),key=new AtomicReference<>();
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");for(String file:List.of("V002__ar_audit.sql","V011__ar_outbox.sql"))for(String sql:Files.readString(Path.of("../scratch/dbddl/"+file)).split(";"))if(!sql.isBlank())jdbc.execute(sql);scope=UUID.randomUUID().getMostSignificantBits()>>>1;server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);executor=Executors.newCachedThreadPool();server.setExecutor(executor);server.start();config.setEnabled(true);config.setAllowLoopbackHttp(true);config.setRequestTimeoutMillis(300);config.setLeaseSeconds(10);config.setMaxAttempts(3);config.setRetryBaseSeconds(2);config.setRetryMaxSeconds(3);config.setReceivers(Map.of(scope,new OutboxProperties.Receiver(uri("/events"),"test-secret")));}
 @AfterEach void close(){config.setEnabled(false);config.setReceivers(Map.of());server.stop(0);executor.shutdownNow();}
 URI uri(String path){return URI.create("http://127.0.0.1:"+server.getAddress().getPort()+path);}
 long enqueue(){String key=UUID.randomUUID().toString();jdbc.update("INSERT INTO oms_ar_lifecycle_event(event_type,occurred_at,actor,correlation_id,created_by,updated_by) VALUES('TEST',NOW(6),'dispatch-test',?,'dispatch-test','dispatch-test')",key);long event=jdbc.queryForObject("SELECT id FROM oms_ar_lifecycle_event WHERE correlation_id=?",Long.class,key);jdbc.update("INSERT INTO oms_ar_outbox(event_id,legal_entity_id,destination,payload,created_by,updated_by) VALUES(?,?,'FINANCE_EVENTS','{\"amount\":\"9999999999999999.12\"}','dispatch-test','dispatch-test')",event,scope);return jdbc.queryForObject("SELECT id FROM oms_ar_outbox WHERE event_id=?",Long.class,event);}
 String status(long id){return jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE id=?",String.class,id);}
 void receive(HttpExchange e)throws java.io.IOException{calls.incrementAndGet();body.set(new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));authorization.set(e.getRequestHeaders().getFirst("Authorization"));key.set(e.getRequestHeaders().getFirst("Idempotency-Key"));}
 @Test @DisplayName("发送保存的原始payload及幂等键，成功后不再发送")void success(){long id=enqueue();server.createContext("/events",e->{receive(e);e.sendResponseHeaders(204,-1);e.close();});assertThat(service.dispatchOnce()).isEqualTo(1);assertThat(status(id)).isEqualTo("SENT");assertThat(body.get()).isEqualTo(jdbc.queryForObject("SELECT payload FROM oms_ar_outbox WHERE id=?",String.class,id));assertThat(authorization.get()).isEqualTo("Bearer test-secret");assertThat(key.get()).contains("FINANCE_EVENTS");assertThat(service.dispatchOnce()).isZero();assertThat(calls.get()).isEqualTo(1);}
 @Test @DisplayName("默认关闭或无配置时保留队列")void disabled(){long id=enqueue();config.setEnabled(false);assertThat(service.dispatchOnce()).isZero();assertThat(status(id)).isEqualTo("PENDING");config.setEnabled(true);config.setReceivers(Map.of());assertThat(service.dispatchOnce()).isZero();assertThat(status(id)).isEqualTo("PENDING");assertThat(new OutboxProperties().isEnabled()).isFalse();assertThat(new OutboxProperties().isSchedulingEnabled()).isFalse();}
 @Test @DisplayName("失败采用有上限的指数退避并保留相同幂等键")void retries(){long id=enqueue();server.createContext("/events",e->{receive(e);byte[] secret="remote secret should not persist".getBytes(StandardCharsets.UTF_8);e.sendResponseHeaders(503,secret.length);e.getResponseBody().write(secret);e.close();});String original=null;for(int i=1;i<=3;i++){assertThat(service.dispatchOnce()).isEqualTo(1);if(original==null)original=key.get();else assertThat(key.get()).isEqualTo(original);assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("HTTP_503");int delay=jdbc.queryForObject("SELECT TIMESTAMPDIFF(SECOND,NOW(6),next_attempt_at) FROM oms_ar_outbox WHERE id=?",Integer.class,id);assertThat(delay).isBetween(i==1?1:2,i==1?2:3);if(i<3){assertThat(status(id)).isEqualTo("RETRY");jdbc.update("UPDATE oms_ar_outbox SET next_attempt_at=NOW(6) WHERE id=?",id);}}assertThat(status(id)).isEqualTo("DEAD");assertThat(service.dispatchOnce()).isZero();}
 @Test @DisplayName("拒绝跟随重定向，凭据不发送给另一个路径")void redirect(){long id=enqueue();var redirected=new AtomicInteger();server.createContext("/events",e->{receive(e);e.getResponseHeaders().add("Location",uri("/other").toString());e.sendResponseHeaders(302,-1);e.close();});server.createContext("/other",e->{redirected.incrementAndGet();e.sendResponseHeaders(204,-1);e.close();});assertThat(service.dispatchOnce()).isEqualTo(1);assertThat(status(id)).isEqualTo("RETRY");assertThat(redirected.get()).isZero();assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("HTTP_302");}
 @Test @DisplayName("总超时包含已收到响应头后的慢正文")void timeout(){long id=enqueue();var release=new CountDownLatch(1);server.createContext("/events",e->{receive(e);e.sendResponseHeaders(200,10);e.getResponseBody().write('x');e.getResponseBody().flush();try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException ex){Thread.currentThread().interrupt();}finally{e.close();}});long start=System.nanoTime();try{assertThat(service.dispatchOnce()).isEqualTo(1);assertThat((System.nanoTime()-start)/1_000_000).isLessThan(2000);assertThat(status(id)).isEqualTo("RETRY");assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("TIMEOUT");}finally{release.countDown();}}
 @Test @DisplayName("网络发送时不占用通知行事务锁，外层回滚不撤销投递结果")void outsideTransaction(){long id=enqueue();config.setRequestTimeoutMillis(2000);var lockVerified=new AtomicBoolean();server.createContext("/events",e->{receive(e);new org.springframework.transaction.support.TransactionTemplate(transactions).execute(s->{jdbc.execute("SET SESSION innodb_lock_wait_timeout=1");assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_outbox WHERE id=? FOR UPDATE",String.class,id)).isEqualTo("PROCESSING");lockVerified.set(true);return null;});e.sendResponseHeaders(204,-1);e.close();});new org.springframework.transaction.support.TransactionTemplate(transactions).execute(s->{assertThat(service.dispatchOnce()).isEqualTo(1);s.setRollbackOnly();return null;});assertThat(lockVerified).isTrue();assertThat(status(id)).isEqualTo("SENT");}
 @Test @DisplayName("无效地址及不覆盖请求超时的租约在领取前拒绝")void invalid(){long id=enqueue();config.setReceivers(Map.of(scope,new OutboxProperties.Receiver(URI.create("https://user:password@example.com/events"),"secret")));assertThatThrownBy(()->service.dispatchOnce()).isInstanceOf(IllegalArgumentException.class);assertThat(status(id)).isEqualTo("PENDING");config.setReceivers(Map.of(scope,new OutboxProperties.Receiver(uri("/events"),"secret")));config.setLeaseSeconds(1);config.setRequestTimeoutMillis(2000);assertThatThrownBy(()->service.dispatchOnce()).isInstanceOf(IllegalArgumentException.class);assertThat(status(id)).isEqualTo("PENDING");}
 @Test @DisplayName("接收成功但确认丢失后重发，接收端按同一幂等键去重")void lostAcknowledgement(){
  long id=enqueue();var seen=ConcurrentHashMap.<String>newKeySet();var applied=new AtomicInteger();var release=new CountDownLatch(1);
  server.createContext("/events",e->{receive(e);boolean first=seen.add(e.getRequestHeaders().getFirst("Idempotency-Key"));if(first){applied.incrementAndGet();try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException ex){Thread.currentThread().interrupt();}}try{e.sendResponseHeaders(204,-1);}finally{e.close();}});
  try{assertThat(service.dispatchOnce()).isEqualTo(1);assertThat(status(id)).isEqualTo("RETRY");assertThat(applied.get()).isEqualTo(1);jdbc.update("UPDATE oms_ar_outbox SET next_attempt_at=NOW(6) WHERE id=?",id);assertThat(service.dispatchOnce()).isEqualTo(1);assertThat(status(id)).isEqualTo("SENT");assertThat(calls.get()).isEqualTo(2);assertThat(applied.get()).isEqualTo(1);}finally{release.countDown();}
 }
 @Test @DisplayName("未配置的主体不发送，连接拒绝转为安全错误分类")void unavailable(){
  long id=enqueue();jdbc.update("UPDATE oms_ar_outbox SET legal_entity_id=? WHERE id=?",scope+1,id);assertThat(service.dispatchOnce()).isZero();assertThat(status(id)).isEqualTo("PENDING");jdbc.update("UPDATE oms_ar_outbox SET legal_entity_id=? WHERE id=?",scope,id);server.stop(0);assertThat(service.dispatchOnce()).isEqualTo(1);assertThat(status(id)).isEqualTo("RETRY");assertThat(jdbc.queryForObject("SELECT last_error FROM oms_ar_outbox WHERE id=?",String.class,id)).isEqualTo("IO_ERROR");
 }

}
